  "jaratkaru_n": { "av": "🌺", "en": "Jaratkārū (Vāsuki's sister)", "te": "జరత్కారువు (వాసుకి చెల్లెలు)", "d": "The serpent-princess, sister of Vāsuki, given in marriage to the sage Jaratkāru; mother of Āstīka. Later Purāṇas worship her as the goddess Manasā.", "dt": "వాసుకి చెల్లెలైన నాగకన్య; జరత్కారు మహర్షికి భార్య, ఆస్తీకుని తల్లి. తర్వాతి పురాణాలు ఆమెను మనసా దేవిగా పూజిస్తాయి." },
  "vasuki": { "av": "🐍", "en": "Vāsuki", "te": "వాసుకి", "d": "King of the serpents, eldest of Kadrū's sons, who served as the rope when the ocean was churned. He gave his sister to the sage Jaratkāru.", "dt": "నాగరాజు, కద్రువ కొడుకులలో పెద్దవాడు. క్షీరసాగర మథనంలో తాడుగా ఉన్నాడు. తన చెల్లెలిని జరత్కారు మహర్షికిచ్చి పెళ్ళి చేశాడు." },
  "elapatra": { "av": "🐍", "en": "Elāpatra", "te": "ఏలాపత్రుడు", "d": "A wise serpent, son of Kadrū, who as a little one overheard Brahmā promise that a sage's son would save the good serpents.", "dt": "కద్రువ కుమారుడైన వివేకం గల నాగుడు. చిన్నప్పుడు, ఒక ముని కొడుకు మంచి నాగులను కాపాడతాడని బ్రహ్మదేవుడు చెప్పిన మాట విన్నాడు." },
  "yayavaras": { "av": "🌾", "en": "The Yāyāvaras", "te": "యాయావరులు", "d": "Jaratkāru's ancestors, a family of wandering sages who kept no store. He found them hanging head-down over a pit because their line was about to end.", "dt": "జరత్కారుని పితరులు — ఏమీ దాచుకోకుండా సంచరించే మునుల వంశం. వంశం ఆగిపోబోతున్నందున తలకిందులుగా గోతి మీద వేలాడుతూ కనిపించారు." },
